const payload = JSON.stringify({ 
  mimeType: 'image/jpeg', 
  imageBase64: '' 
});

const res = await fetch('http://localhost:8081/extract', { 
  method: 'POST', 
  headers: { 'Content-Type': 'application/json' }, 
  body: payload 
});

console.log('Status:', res.status);
console.log(await res.text());